// 圆通电子面单 PDF 生成器（浏览器版，@pdf-lib）
// 依赖：先加载 https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js
//       和 https://unpkg.com/@pdf-lib/fontkit@1.1.1/dist/fontkit.umd.min.js
// 用法：const bytes = await generateFacesheetPdf(data);  // Uint8Array
(function (global) {
  const FONT_B64 = "";
  const ICON_RECV_B64 = "";
  const ICON_SEND_B64 = "";
  const W = 213.0, H = 366.0;

  function b64ToBytes(b64) {
    if (typeof atob === 'function') {
      const bin = atob(b64); const arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      return arr;
    }
    return Uint8Array.from(Buffer.from(b64, 'base64'));
  }

  // Code128
  const C128 = {0:[2,1,2,2,2,2],1:[2,2,2,1,2,2],2:[2,2,2,2,2,1],3:[1,2,1,2,2,3],4:[1,2,1,3,2,2],5:[1,3,1,2,2,2],6:[1,2,2,2,1,3],7:[1,2,2,3,1,2],8:[1,3,2,2,1,2],9:[2,2,1,2,1,3],10:[2,2,1,3,1,2],11:[2,3,1,2,1,2],12:[1,1,2,2,3,2],13:[1,2,2,1,3,2],14:[1,2,2,2,3,1],15:[1,1,3,2,2,2],16:[1,2,3,1,2,2],17:[1,2,3,2,2,1],18:[2,2,3,2,1,1],19:[2,2,1,1,3,2],20:[2,2,1,2,3,1],21:[2,1,3,2,1,2],22:[2,2,3,1,1,2],23:[3,1,2,1,3,1],24:[3,1,1,2,2,2],25:[3,2,1,1,2,2],26:[3,2,1,2,2,1],27:[3,1,2,2,1,2],28:[3,2,2,1,1,2],29:[3,2,2,2,1,1],30:[2,1,2,1,2,3],31:[2,1,2,3,2,1],32:[2,3,2,1,2,1],33:[2,1,1,1,2,3],34:[2,1,1,3,2,1],35:[2,3,1,1,2,1],36:[2,1,2,1,1,3],37:[2,1,2,3,1,1],38:[2,3,2,1,1,1],39:[2,1,1,1,3,2],40:[2,1,1,2,3,1],41:[2,1,1,3,3,1],42:[1,1,2,1,2,3],43:[1,1,2,3,2,1],44:[1,3,2,1,2,1],45:[1,1,1,1,2,3],46:[1,1,1,3,2,1],47:[1,3,1,1,2,1],48:[1,1,2,1,1,3],49:[1,1,2,3,1,1],50:[1,3,2,1,1,1],51:[1,1,1,1,3,2],52:[1,1,1,2,3,1],53:[1,1,1,3,3,1],54:[1,3,1,1,3,1],55:[1,1,2,1,3,1],56:[1,1,2,2,1,3],57:[1,1,2,3,1,2],58:[1,3,1,2,1,2],59:[1,1,1,2,2,3],60:[1,1,1,3,2,2],61:[1,3,1,2,2,2],62:[1,1,2,2,3,1],63:[1,1,2,3,3,1],64:[1,3,1,2,3,1],65:[1,1,1,2,3,2],66:[1,1,1,3,3,2],67:[1,3,1,1,3,2],68:[1,1,2,2,1,3],69:[1,1,2,3,1,3],70:[1,3,1,2,1,3],71:[1,1,1,2,1,3],72:[1,1,1,3,1,3],73:[1,3,1,1,1,3],74:[1,1,2,2,3,1],75:[1,1,2,3,3,1],76:[1,3,1,2,3,1],77:[1,1,1,2,3,1],78:[1,1,1,3,3,1],79:[1,3,1,1,3,1],80:[1,1,2,1,1,3],81:[1,1,2,3,1,3],82:[1,3,1,2,1,3],83:[1,1,1,2,1,3],84:[1,1,1,3,1,3],85:[1,3,1,1,1,3],86:[2,1,1,2,2,3],87:[2,1,1,3,2,3],88:[2,3,1,1,2,3],89:[2,1,1,1,3,3],90:[2,1,1,3,3,3],91:[2,3,1,1,3,3],92:[2,1,2,1,2,3],93:[2,1,2,3,2,3],94:[2,3,2,1,2,3],95:[2,1,1,1,1,3],96:[2,1,1,3,1,3],97:[2,3,1,1,1,3],98:[2,1,2,1,3,1],99:[2,1,2,3,3,1],100:[2,3,2,1,3,1],101:[2,1,1,1,3,1],102:[2,1,1,3,3,1],103:[2,3,1,1,3,1],104:[2,1,2,1,1,3],105:[2,1,2,3,1,3],106:[2,3,2,1,1,3]};
  const VALS = {}; "0123456789".split('').forEach((c,i)=>VALS[c]=i);
  "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('').forEach((c,i)=>VALS[c]=33+i);
  VALS['-']=11; VALS[' ']=32;
  function code128Bars(text) {
    let sum = 103, w = 1;
    for (let i = 0; i < text.length; i++) { const v = VALS[text[i]]; sum += v * w; w++; }
    const codes = [103];
    for (const ch of text) codes.push(VALS[ch]);
    codes.push(sum % 103); codes.push(106);
    let bars = [];
    for (const c of codes) bars = bars.concat(C128[c]);
    return bars;
  }

  async function generateFacesheetPdf(d) {
    const PDFLib = global.PDFLib;
    const fontkit = global.fontkit;
    const { PDFDocument, rgb, degrees } = PDFLib;
    const doc = await PDFDocument.create();
    doc.registerFontkit(fontkit);
    const page = doc.addPage([W, H]);
    const black = rgb(0, 0, 0);
    const font = await doc.embedFont(b64ToBytes(FONT_B64));
    const iconRecv = await doc.embedPng(b64ToBytes(ICON_RECV_B64));
    const iconSend = await doc.embedPng(b64ToBytes(ICON_SEND_B64));

    const line = (x0, y0, x1, y1, w) => page.drawLine({ start:{x:x0,y:y0}, end:{x:x1,y:y1}, thickness:w||0.8, color:black });
    const text = (s, x, ytop, size) => page.drawText(s, { x, y: H - ytop - size*0.85, size, font, color: black });
    const vtext = (s, x, ybottom, size, reverse) => {
      const chars = reverse ? s.split('') : s.split('').reverse();
      let yy = ybottom;
      for (const ch of chars) { page.drawText(ch, { x, y: yy, size, font, color: black, rotate: degrees(90) }); yy += size*1.1; }
    };
    const drawBarcode = (x, y, h, targetW) => {
      const bars = code128Bars(d.mailNo);
      const total = bars.reduce((a,b)=>a+b, 0);
      const mw = targetW / total;
      let cx = x, draw = true;
      for (const m of bars) { const bw = m * mw; if (draw) page.drawRectangle({ x: cx, y, width: bw, height: h, color: black }); cx += bw; draw = !draw; }
    };

    const mn = d.mailNo || '';
    // 顶部
    text(mn, 3.7, 15.3, 8);
    text(d.date || '', 2.8, 24.9, 7);
    text((d.time||'') + ' 第1/1个', 56.9, 24.9, 7);
    line(14.4, H-34, 198.5, H-34);
    text(d.seg || '-', 23.6, 34, 23);
    line(14.4, H-59.5, 198.5, H-59.5);
    // 条码
    drawBarcode(16.2, H-93.3, 30.8, 143.7);
    // 大单号
    text(mn, 32.7, 93.5, 11);
    line(14.4, H-104.9, 164.5, H-104.9);
    // 目的地
    page.drawRectangle({ x:16.0, y:H-122.2, width:19.7, height:17.3, borderColor:black, borderWidth:0.8 });
    text(d.landmark || '', 36.9, 105.9, 15);
    line(14.4, H-123.6, 164.5, H-123.6);
    line(14.3, H-138, 164.5, H-138);
    // 收件人
    page.drawImage(iconRecv, { x:15.7, y:H-151.5, width:13.3, height:11.4 });
    text(d.receiver.name || '', 27.3, 140.9, 9);
    text(d.receiver.phone || '', 27.3, 151.2, 9);
    let ay = 161.5;
    (d.receiver.addressLines || []).forEach(a => { text(a, 27.3, ay, 9); ay += 10.4; });
    line(14.3, H-195.6, 164.5, H-195.6);
    // 寄件人
    page.drawImage(iconSend, { x:13.6, y:H-210.3, width:10.5, height:12.7 });
    text(d.sender.name || '', 25.2, 195.8, 12);
    text(d.sender.address || '', 25.2, 209.5, 12);
    line(14.4, H-223.9, 199.3, H-223.9);
    // 编码行
    text(d.code || '', 2.2, 227.2, 9);
    text(d.qty || '', 2.2, 236.6, 9);
    // 右侧竖排单号 + 竖条码
    vtext(mn, 167.6, H-177, 3.5);
    drawBarcode(176.4, H-214.5, 21.7, 147.0); // 竖条码（横画，旋转由PDF查看器处理？）—— 简化
    line(164.5, H-223.9, 164.5, H-59.8, 0.8);
    // 4 处边缘竖排
    vtext(mn, 3.6, H-107.9, 4);
    vtext(mn, 4.3, H-205.5, 4);
    vtext(mn, 202.0, H-107.7, 4, true);
    vtext(mn, 202.2, H-204.2, 4, true);
    // 合计 / 已验视
    text('合计 ' + (d.totalQty || 1), 149.4, 285.9, 9);
    text('已验视', 173.5, 292, 8);
    // 底部明细表
    line(2, 62, 211, 62);
    line(2, 0, 211, 0);
    text('采购单号   款号   颜色   码   数量', 3, 366-56, 9);
    let yy = 366-50;
    (d.rows || []).forEach(r => { text(d.poId + '   ' + r[0] + '   ' + r[1] + '   ' + r[2] + '   ' + r[3], 3, yy, 9); yy += 11; });

    const bytes = await doc.save();
    return bytes;
  }

  global.generateFacesheetPdf = generateFacesheetPdf;
})(typeof window !== 'undefined' ? window : globalThis);
